const {
    default: initWasm,
    convex_hull,
    convex_hull_rgba,
    sat_batch,
    first_order_lead_angle,
    swept_circle_polygon_time,
    swept_polygon_polygon_time,
} = require("./nova_wasm_bindgen.js");

const EMBEDDED_WASM_BASE64 = "";
let initialization;
let initialized = false;

function decodeBase64(value) {
    const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    const bytes = new Uint8Array(Math.floor(value.length * 3 / 4));
    let buffer = 0;
    let bits = 0;
    let offset = 0;

    for (let i = 0; i < value.length; i++) {
        const digit = alphabet.indexOf(value[i]);
        if (digit < 0) {
            continue;
        }
        buffer = (buffer << 6) | digit;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            bytes[offset++] = (buffer >> bits) & 0xff;
        }
    }

    return offset === bytes.length ? bytes : bytes.slice(0, offset);
}

function init() {
    if (!initialization) {
        initialization = initWasm({ module_or_path: decodeBase64(EMBEDDED_WASM_BASE64) }).then(() => {
            initialized = true;
        });
    }
    return initialization;
}

function isInitialized() {
    return initialized;
}

function requireInitialized() {
    if (!initialized) {
        throw new Error("nova_wasm.init() must resolve before using the synchronous API");
    }
}

function convexHull(points) {
    requireInitialized();
    return convex_hull(points);
}

function convexHullRgba(rgba, width, height, alphaThreshold) {
    requireInitialized();
    return convex_hull_rgba(rgba, width, height, alphaThreshold);
}

function firstOrderLeadAngle(posX, posY, velX, velY, targetPosX, targetPosY, targetVelX, targetVelY, shotSpeed) {
    requireInitialized();
    return first_order_lead_angle(posX, posY, velX, velY, targetPosX, targetPosY, targetVelX, targetVelY, shotSpeed);
}

function satBatch(
    aVertices,
    aOffsets,
    aPositions,
    aRotations,
    bVertices,
    bOffsets,
    bPositions,
    bRotations,
    pairs,
) {
    requireInitialized();
    return sat_batch(
        aVertices,
        aOffsets,
        aPositions,
        aRotations,
        bVertices,
        bOffsets,
        bPositions,
        bRotations,
        pairs,
    );
}

function sweptCirclePolygonTime(
    cx,
    cy,
    radius,
    polyVertices,
    polyOx,
    polyOy,
    vx,
    vy,
) {
    requireInitialized();
    return swept_circle_polygon_time(
        cx,
        cy,
        radius,
        polyVertices,
        polyOx,
        polyOy,
        vx,
        vy,
    );
}

function sweptPolygonPolygonTime(
    aVertices,
    aOx,
    aOy,
    bVertices,
    bOx,
    bOy,
    vx,
    vy,
) {
    requireInitialized();
    return swept_polygon_polygon_time(
        aVertices,
        aOx,
        aOy,
        bVertices,
        bOx,
        bOy,
        vx,
        vy,
    );
}

module.exports = {
    convexHull,
    convexHullRgba,
    firstOrderLeadAngle,
    init,
    isInitialized,
    satBatch,
    sweptCirclePolygonTime,
    sweptPolygonPolygonTime,
};
